1132	export function executeWorkflow(workflow, input = {}) {
1133	  const nodes = validateWorkflow(workflow);
1134	  // Business operations are asynchronous: the synchronous entry must refuse
1135	  // a workflow that names any before a single node executes.
1136	  for (const node of nodes.values()) {
1137	    const binding = actionBindings.get(node);
1138	    if (binding && binding.name !== null) {
